ent":false},{"member_no":13,"meeting_no":2,"is_present":false},{"member_no":13,"meeting_no":3,"is_present":false},{"member_no":13,"meeting_no":4,"is_present":false},{"member_no":13,"meeting_no":5,"is_present":false},{"member_no":13,"meeting_no":6,"is_present":false},{"member_no":13,"meeting_no":7,"is_present":false},{"member_no":13,"meeting_no":8,"is_present":false},{"member_no":13,"meeting_no":9,"is_present":false},{"member_no":13,"meeting_no":10,"is_present":false},{"member_no":13,"meeting_no":11,"is_present":false},{"member_no":13,"meeting_no":12,"is_present":false},{"member_no":13,"meeting_no":13,"is_present":false},{"member_no":13,"meeting_no":14,"is_present":false},{"member_no":13,"meeting_no":15,"is_present":false},{"member_no":13,"meeting_no":16,"is_present":false},{"member_no":13,"meeting_no":17,"is_present":false},{"member_no":13,"meeting_no":18,"is_present":false},{"member_no":13,"meeting_no":19,"is_present":false},{"member_no":13,"meeting_no":20,"is_present":false},{"member_no":13,"meeting_no":21,"is_present":false},{"member_no":13,"meeting_no":22,"is_present":false},{"member_no":13,"meeting_no":23,"is_present":false},{"member_no":19,"meeting_no":1,"is_present":false},{"member_no":19,"meeting_no":2,"is_present":false},{"member_no":19,"meeting_no":3,"is_present":false},{"member_no":19,"meeting_no":4,"is_present":false},{"member_no":19,"meeting_no":5,"is_present":false},{"member_no":19,"meeting_no":6,"is_present":false},{"member_no":19,"meeting_no":7,"is_present":false},{"member_no":19,"meeting_no":8,"is_present":false},{"member_no":19,"meeting_no":9,"is_present":false},{"member_no":19,"meeting_no":10,"is_present":false},{"member_no":19,"meeting_no":11,"is_present":false},{"member_no":19,"meeting_no":12,"is_present":false},{"member_no":19,"meeting_no":13,"is_present":false},{"member_no":19,"meeting_no":14,"is_present":false},{"member_no":19,"meeting_no":15,"is_present":false},{"member_no":19,"meeting_no":16,"is_present":false},{"member_no":19,"meeting_no":17,"is_present":false},{"member_no":19,"meeting_no":18,"is_present":false},{"member_no":19,"meeting_no":19,"is_present":false},{"member_no":19,"meeting_no":20,"is_present":true},{"member_no":19,"meeting_no":21,"is_present":false},{"member_no":19,"meeting_no":22,"is_present":false},{"member_no":19,"meeting_no":23,"is_present":true}]$attendance_json$::jsonb;
  m jsonb;
  a jsonb;
  ai jsonb;
  na jsonb;
  v_meeting_id uuid;
  v_member_id uuid;
  v_sort int;
  v_meetings_inserted int := 0;
  v_agenda_inserted int := 0;
  v_next_agenda_inserted int := 0;
  v_attendance_inserted int := 0;
BEGIN
  FOR m IN SELECT * FROM jsonb_array_elements(v_meetings) LOOP
    SELECT id INTO v_meeting_id FROM public.meetings WHERE meeting_no = (m->>'meeting_no')::int;
    IF v_meeting_id IS NOT NULL THEN
      CONTINUE; -- already imported, skip entirely (idempotent by meeting_no)
    END IF;

    INSERT INTO public.meetings (meeting_no, meeting_date, location, duration,
                                 next_meeting_date, next_meeting_location, next_meeting_duration)
    VALUES ((m->>'meeting_no')::int, (m->>'meeting_date')::date, m->>'location', m->>'duration',
            NULLIF(m->>'next_meeting_date','')::date, m->>'next_meeting_location', m->>'next_meeting_duration')
    RETURNING id INTO v_meeting_id;
    v_meetings_inserted := v_meetings_inserted + 1;

    v_sort := 0;
    FOR ai IN SELECT * FROM jsonb_array_elements(COALESCE(m->'agenda_items', '[]'::jsonb)) LOOP
      INSERT INTO public.meeting_agenda_items (meeting_id, sort_order, agenda, decision_summary)
      VALUES (v_meeting_id, v_sort, ai->>'agenda', ai->>'summary');
      v_sort := v_sort + 1;
      v_agenda_inserted := v_agenda_inserted + 1;
    END LOOP;

    v_sort := 0;
    FOR na IN SELECT * FROM jsonb_array_elements(COALESCE(m->'next_agenda_items', '[]'::jsonb)) LOOP
      INSERT INTO public.meeting_next_agenda_items (meeting_id, sort_order, item)
      VALUES (v_meeting_id, v_sort, na #>> '{}');
      v_sort := v_sort + 1;
      v_next_agenda_inserted := v_next_agenda_inserted + 1;
    END LOOP;

    FOR a IN SELECT * FROM jsonb_array_elements(v_attendance) WHERE (value->>'meeting_no')::int = (m->>'meeting_no')::int LOOP
      SELECT id INTO v_member_id FROM public.members WHERE member_no = (a->>'member_no')::int;
      IF v_member_id IS NULL THEN
        RAISE EXCEPTION 'No member with member_no % for meeting %', a->>'member_no', m->>'meeting_no';
      END IF;
      INSERT INTO public.meeting_attendance (meeting_id, member_id, is_present)
      VALUES (v_meeting_id, v_member_id, (a->>'is_present')::boolean)
      ON CONFLICT (meeting_id, member_id) DO NOTHING;
      v_attendance_inserted := v_attendance_inserted + 1;
    END LOOP;
  END LOOP;

  RAISE NOTICE 'Meetings import: % meetings, % agenda items, % next-agenda items, % attendance rows',
    v_meetings_inserted, v_agenda_inserted, v_next_agenda_inserted, v_attendance_inserted;
END;
$import_meetings$;
